// Hub plugins: how packets A (live), B (mirror), C (alexa, mcp) and the static mounts attach to
// the hub server without editing it. Owned by the lead (contract v2): packets do not edit this file.
//
// Routing order in src/hub/server.ts, for every HTTP request:
//   1. the public-access gate (src/hub/gate.ts): a public request outside the allow-list gets 403
//   2. fixture mode (--demo --fixture-v2): the frozen examples in fixtures/contract-v2/
//   3. plugins, in registry order, for a path under one of their `prefixes` (OPTIONS included):
//      `route` returns true when it answered, false to fall through
//   4. the generic OPTIONS answer, then the v1 core routes, then 404 not_found
// Bridge `app` frames: the core topics first (card.request, attempt.submit, session.*); any other
// topic is offered to each plugin's `onApp` in registry order until one returns something other
// than undefined (null = handled, no intent).
import type { IncomingMessage, ServerResponse } from "node:http";
import type { BridgeHub, IntentResult, Room } from "tv-voice-bridge/hub";
import type { AppMsg, PeerInfo } from "tv-voice-bridge";
import type { CoachHub, HubEvent } from "./core.js";
import type { Setup } from "./setup.js";
import type { PluginInfo, PluginStatus, RoomTopic, SequencedTopic } from "./contract.js";

export type Log = (event: string, data?: Record<string, unknown>) => void;

export interface PluginCtx {
  hub: CoachHub;
  setup: Setup;
  bridge: BridgeHub;
  stateDir: string | null; // live: "real"; demo: "out/demo" (or null: memory only). Plugins write under <stateDir>/<name>/
  pace: number; // demo replay pace (1 = real time)
  demo: boolean;
  fixtureV2: boolean;
  log: Log; // JSON-line logger: event names and ids only, never transcript text or tokens
  // Sequenced: seq + SSE + /api/events/recent + every bridge peer. Throws for room topics.
  publish(topic: SequencedTopic, data: Record<string, unknown>): HubEvent;
  // Room-scoped: one room's `screen` peers only (no seq, never SSE). `room` is a Room or its code;
  // omit it to send to the screens of every room. Returns the number of screens reached.
  broadcastToScreens(room: Room | string | null, topic: RoomTopic, payload: unknown): number;
  // The hub's own loopback base URL (http://127.0.0.1:<port>), for packet C's hub client.
  // Loopback requests are LAN requests for the gate; never forward client headers through it.
  selfUrl(): string;
  // Token checks (the tokens themselves are never handed to plugins or put in responses).
  auth: { mcpBearerOk(authorization: string | undefined): boolean; pairTokenOk(k: string | null | undefined): boolean };
  // The request must authenticate (signature, bearer): it is public, or a tunnel is declared
  // (PUBLIC_BASE_URL), since a TCP tunnel looks like loopback (gate.ts mustAuthenticate).
  isPublic(req: IncomingMessage): boolean;
  // The hub's JSON writer (no-store; an allowed Origin is already echoed). It masks every string for
  // the request's mode, unless the plugin masked the body itself (`premasked`, as the Alexa plugin does).
  json(res: ServerResponse, status: number, data: unknown, opts?: { premasked?: boolean }): void;
  readJson(req: IncomingMessage): Promise<Record<string, unknown>>; // <= 64 kB JSON object body ({} if empty)
}

export interface HubPlugin {
  name: string;
  prefixes: string[]; // path prefixes this plugin owns, matched on segment boundaries
  attach?(ctx: PluginCtx): void; // once, before the server listens
  route?(req: IncomingMessage, res: ServerResponse, url: URL, ctx: PluginCtx): Promise<boolean>;
  onApp?(room: Room, msg: AppMsg, from: PeerInfo, ctx: PluginCtx): IntentResult | undefined;
  describe?(): Omit<PluginInfo, "name" | "prefixes">;
  stop?(): void;
}

// "/api/live" matches "/api/live" and "/api/live/mode", not "/api/lively". "/tv/" also matches "/tv".
export function underPrefix(path: string, prefix: string): boolean {
  const p = prefix.endsWith("/") ? prefix.slice(0, -1) : prefix;
  return path === p || path.startsWith(`${p}/`);
}

// "GET /api/recaps/<id>" matches "GET /api/recaps/rcp_1".
export function matchRoute(pattern: string, method: string, path: string): Record<string, string> | null {
  const [m, p] = pattern.split(" ") as [string, string];
  if (m !== method) return null;
  const names: string[] = [];
  const re = new RegExp(`^${p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/<(\w+)>/g, (_s, n: string) => (names.push(n), "([\\w.:-]+)"))}$`);
  const hit = re.exec(path);
  if (!hit) return null;
  return Object.fromEntries(names.map((n, i) => [n, hit[i + 1]!]));
}

export interface StubSpec {
  name: string;
  owner: string;
  prefixes: string[];
  routes: string[];
  topics?: string[];
  note?: string;
}

// A plugin that owns its routes but answers 501 not_implemented until its packet lands.
export function stubPlugin(spec: StubSpec): HubPlugin {
  const status: PluginStatus = "stub";
  return {
    name: spec.name,
    prefixes: spec.prefixes,
    async route(req, res, url, ctx) {
      const method = req.method ?? "GET";
      const hit = spec.routes.find((r) => matchRoute(r, method, url.pathname));
      if (!hit) return false;
      ctx.json(res, 501, { error: "not_implemented", message: `${hit} belongs to the ${spec.name} plugin (${spec.owner}) and is not implemented yet; the payload is frozen in docs/CONTRACT.md (v2)`, plugin: spec.name, owner: spec.owner, routes: spec.routes });
      return true;
    },
    describe: () => ({ owner: spec.owner, status, routes: spec.routes, topics: spec.topics, note: spec.note ?? "stub: answers 501 not_implemented" }),
  };
}
